-- 02 Booking core
DROP TABLE IF EXISTS dbo.PaymentMethod;
DROP TABLE IF EXISTS dbo.Appointment;
DROP TABLE IF EXISTS dbo.Customer;

-- 01 Foundation
DROP TABLE IF EXISTS dbo.Service;
DROP TABLE IF EXISTS dbo.ServiceCategory;
