-- ==================================================================
-- Source: src/Tables/01_foundation/dbo.Business.sql
-- ==================================================================
-- Business: the top-level tenant. Everything in the foundation cluster
-- hangs off this table directly or through Location / ServiceCategory.
CREATE TABLE dbo.Business (
    BusinessID   INT IDENTITY(1,1) NOT NULL,
    Name         VARCHAR(150)      NOT NULL,
    Description  VARCHAR(500)      NULL,

    CONSTRAINT PK_Business PRIMARY KEY (BusinessID)
);
GO

-- ==================================================================
-- Source: src/Tables/01_foundation/dbo.Location.sql
-- ==================================================================
-- Location: a physical site operated by a Business (1 Business : many Locations).
CREATE TABLE dbo.Location (
    LocationID      INT IDENTITY(1,1) NOT NULL,
    BusinessID      INT               NOT NULL,
    Street          VARCHAR(150)      NOT NULL,
    City            VARCHAR(100)      NOT NULL,
    State           VARCHAR(50)       NOT NULL,
    Zip             VARCHAR(10)       NOT NULL,
    OperatingHours  VARCHAR(255)      NULL,
    ContactPhone    VARCHAR(20)       NOT NULL,
    Website         VARCHAR(255)      NULL,

    CONSTRAINT PK_Location PRIMARY KEY (LocationID),
    CONSTRAINT FK_Location_Business
        FOREIGN KEY (BusinessID) REFERENCES dbo.Business (BusinessID)
);
GO

-- ==================================================================
-- Source: src/Tables/01_foundation/dbo.CancellationPolicy.sql
-- ==================================================================
-- CancellationPolicy: one policy per Location (1:1, enforced by the UNIQUE
-- constraint on LocationID). Changed from the P3 design, where the policy
-- belonged to Business, so each location of a multi-location business can
-- set its own rules. Must be created AFTER dbo.Location.
CREATE TABLE dbo.CancellationPolicy (
    CancellationPolicyID  INT IDENTITY(1,1) NOT NULL,
    LocationID            INT               NOT NULL,
    NoticePeriod          INT               NOT NULL,  -- hours of notice required
    FeeAmount             DECIMAL(10,2)     NOT NULL,
    RefundRule            VARCHAR(255)      NULL,

    CONSTRAINT PK_CancellationPolicy PRIMARY KEY (CancellationPolicyID),
    CONSTRAINT UQ_CancellationPolicy_LocationID UNIQUE (LocationID),
    CONSTRAINT FK_CancellationPolicy_Location
        FOREIGN KEY (LocationID) REFERENCES dbo.Location (LocationID),
    CONSTRAINT CK_CancellationPolicy_NoticePeriod CHECK (NoticePeriod >= 0),
    CONSTRAINT CK_CancellationPolicy_FeeAmount    CHECK (FeeAmount >= 0)
);
GO

-- ==================================================================
-- Source: src/Tables/01_foundation/dbo.LocationSocialMedia.sql
-- ==================================================================
-- LocationSocialMedia: social accounts for a Location (1 Location : many accounts).
-- The UNIQUE constraint stops the same platform being listed twice for one location.
CREATE TABLE dbo.LocationSocialMedia (
    LocationSocialMediaID  INT IDENTITY(1,1) NOT NULL,
    LocationID             INT               NOT NULL,
    Platform               VARCHAR(50)       NOT NULL,
    URL                    VARCHAR(255)      NOT NULL,

    CONSTRAINT PK_LocationSocialMedia PRIMARY KEY (LocationSocialMediaID),
    CONSTRAINT UQ_LocationSocialMedia_Location_Platform UNIQUE (LocationID, Platform),
    CONSTRAINT FK_LocationSocialMedia_Location
        FOREIGN KEY (LocationID) REFERENCES dbo.Location (LocationID)
);
GO

-- ==================================================================
-- Source: src/Tables/01_foundation/dbo.ServiceCategory.sql
-- ==================================================================
-- ServiceCategory: groups a Business's services (1 Business : many categories).
CREATE TABLE dbo.ServiceCategory (
    ServiceCategoryID  INT IDENTITY(1,1) NOT NULL,
    BusinessID         INT               NOT NULL,
    Name               VARCHAR(100)      NOT NULL,
    Description        VARCHAR(500)      NULL,

    CONSTRAINT PK_ServiceCategory PRIMARY KEY (ServiceCategoryID),
    CONSTRAINT FK_ServiceCategory_Business
        FOREIGN KEY (BusinessID) REFERENCES dbo.Business (BusinessID)
);
GO

-- ==================================================================
-- Source: src/Tables/01_foundation/dbo.Service.sql
-- ==================================================================
-- Service: a bookable service within a category (1 ServiceCategory : many Services).
-- Must be created AFTER dbo.ServiceCategory.
CREATE TABLE dbo.Service (
    ServiceID          INT IDENTITY(1,1) NOT NULL,
    ServiceCategoryID  INT               NOT NULL,
    Name               VARCHAR(100)      NOT NULL,
    Description        VARCHAR(500)      NULL,
    EstimatedDuration  INT               NOT NULL,  -- minutes
    Price              DECIMAL(10,2)     NOT NULL,

    CONSTRAINT PK_Service PRIMARY KEY (ServiceID),
    CONSTRAINT FK_Service_ServiceCategory
        FOREIGN KEY (ServiceCategoryID) REFERENCES dbo.ServiceCategory (ServiceCategoryID),
    CONSTRAINT CK_Service_EstimatedDuration CHECK (EstimatedDuration > 0),
    CONSTRAINT CK_Service_Price             CHECK (Price >= 0)
);
GO

-- ==================================================================
-- Source: src/Tables/02_booking_core/dbo.Customer.sql
-- ==================================================================
-- Customer: a person who books appointments. Customers aren't tied to a
-- business, so one customer can book at any location.
-- Phone and email are each optional, but at least one is required, and
-- the preferred contact method must be one that's on file.
-- Must be created BEFORE dbo.Appointment and dbo.PaymentMethod.
CREATE TABLE dbo.Customer (
    CustomerID                INT IDENTITY(1,1) NOT NULL,
    FirstName                 VARCHAR(50)       NOT NULL,
    LastName                  VARCHAR(50)       NOT NULL,
    PhoneNumber               VARCHAR(20)       NULL,
    Email                     VARCHAR(255)      NULL,
    CustomerPreferredContact  VARCHAR(20)       NOT NULL,
    RegistrationDate          DATE              NOT NULL
        CONSTRAINT DF_Customer_RegistrationDate DEFAULT (GETDATE()),

    CONSTRAINT PK_Customer PRIMARY KEY (CustomerID),
    -- A customer must be reachable by at least one channel.
    CONSTRAINT CK_Customer_HasContact
        CHECK (Email IS NOT NULL OR PhoneNumber IS NOT NULL),
    -- The preferred contact must be a supported channel that's on file.
    CONSTRAINT CK_Customer_PreferredContact
        CHECK (   (CustomerPreferredContact = 'Email' AND Email IS NOT NULL)
               OR (CustomerPreferredContact IN ('Phone', 'SMS') AND PhoneNumber IS NOT NULL)),
    -- Basic email shape (xyz@xyz.xyz), same rule as Staff.Email.
    CONSTRAINT CK_Customer_Email
        CHECK (Email IS NULL OR Email LIKE '%_@_%._%')
);
GO

-- Email must be unique when present. A filtered index is used instead of a
-- UNIQUE constraint because UNIQUE in SQL Server allows only one NULL.
CREATE UNIQUE INDEX UQ_Customer_Email
    ON dbo.Customer (Email)
    WHERE Email IS NOT NULL;
GO

-- ==================================================================
-- Source: src/Tables/02_booking_core/dbo.Appointment.sql
-- ==================================================================
-- Appointment: one booking made by a customer (1 Customer : many
-- Appointments). The appointment itself only records who booked and when.
-- The services, staff, time slots, and statuses live on its
-- AppointmentService rows, so one appointment can include several services.
-- Must be created AFTER dbo.Customer.
CREATE TABLE dbo.Appointment (
    AppointmentID  INT IDENTITY(1,1) NOT NULL,
    CustomerID     INT               NOT NULL,
    BookedAt       DATETIME          NOT NULL
        CONSTRAINT DF_Appointment_BookedAt DEFAULT (GETDATE()),

    CONSTRAINT PK_Appointment PRIMARY KEY (AppointmentID),
    CONSTRAINT FK_Appointment_Customer
        FOREIGN KEY (CustomerID) REFERENCES dbo.Customer (CustomerID),
    -- Sanity floor on booking timestamps. "Not in the future" is checked
    -- in tests/02_booking_core_data_rows.sql instead, since a CHECK
    -- against the current time is brittle.
    CONSTRAINT CK_Appointment_BookedAt
        CHECK (BookedAt >= '2020-01-01')
);
GO

-- ==================================================================
-- Source: src/Tables/02_booking_core/dbo.PaymentMethod.sql
-- ==================================================================
-- PaymentMethod: a card a customer has stored on file (1 Customer : many
-- PaymentMethods). Storing a card is optional, so a customer can have
-- none. Only the last four digits are kept, never the full card number.
-- Must be created AFTER dbo.Customer.
CREATE TABLE dbo.PaymentMethod (
    PaymentMethodID  INT IDENTITY(1,1) NOT NULL,
    CustomerID       INT               NOT NULL,
    CardType         VARCHAR(20)       NOT NULL,
    LastFourDigits   CHAR(4)           NOT NULL,
    ExpirationDate   DATE              NOT NULL,

    CONSTRAINT PK_PaymentMethod PRIMARY KEY (PaymentMethodID),
    CONSTRAINT FK_PaymentMethod_Customer
        FOREIGN KEY (CustomerID) REFERENCES dbo.Customer (CustomerID),
    -- Exactly four digits.
    CONSTRAINT CK_PaymentMethod_LastFourDigits
        CHECK (LastFourDigits LIKE '[0-9][0-9][0-9][0-9]'),
    -- Supported card brands.
    CONSTRAINT CK_PaymentMethod_CardType
        CHECK (CardType IN ('Visa', 'Mastercard', 'Amex', 'Discover')),
    -- Cards expire at the end of a month (MM/YY), so the stored date must
    -- be the last day of its month. Deliberately not "in the future",
    -- since that would make old rows invalid over time.
    CONSTRAINT CK_PaymentMethod_ExpirationDate
        CHECK (ExpirationDate = EOMONTH(ExpirationDate))
);
GO

-- ==================================================================
-- Source: src/Tables/03_staff_time/dbo.Staff.sql
-- ==================================================================
-- Staff: an employee who performs services at one Location
-- (1 Location : many Staff). Must be created AFTER dbo.Location.
CREATE TABLE dbo.Staff (
    StaffID      INT IDENTITY(1,1) NOT NULL,
    LocationID   INT               NOT NULL,
    FirstName    VARCHAR(50)       NOT NULL,
    LastName     VARCHAR(50)       NOT NULL,
    Role         VARCHAR(30)       NOT NULL,
    Email        VARCHAR(255)      NOT NULL,
    PhoneNumber  VARCHAR(20)       NULL,

    CONSTRAINT PK_Staff PRIMARY KEY (StaffID),
    CONSTRAINT FK_Staff_Location
        FOREIGN KEY (LocationID) REFERENCES dbo.Location (LocationID),
    -- Each staff member has their own work email.
    CONSTRAINT UQ_Staff_Email UNIQUE (Email),
    -- Basic email shape (xyz@xyz.xyz), same rule as Customer.Email.
    CONSTRAINT CK_Staff_Email CHECK (Email LIKE '%_@_%._%')
);
GO


-- ==================================================================
-- Source: src/Tables/03_staff_time/dbo.StaffService.sql
-- ==================================================================
-- StaffService: associative entity resolving Staff <-> Service (M:N).
-- One row = one staff member can perform one service, at a given proficiency.
-- Must be created AFTER dbo.Staff and dbo.Service.
CREATE TABLE dbo.StaffService (
    StaffServiceID    INT IDENTITY(1,1) NOT NULL,
    StaffID           INT               NOT NULL,
    ServiceID         INT               NOT NULL,
    ProficiencyLevel  VARCHAR(30)       NOT NULL,

    CONSTRAINT PK_StaffService PRIMARY KEY (StaffServiceID),
    CONSTRAINT FK_StaffService_Staff
        FOREIGN KEY (StaffID) REFERENCES dbo.Staff (StaffID),
    CONSTRAINT FK_StaffService_Service
        FOREIGN KEY (ServiceID) REFERENCES dbo.Service (ServiceID),
    -- A staff/service pairing is recorded once (one proficiency per pairing).
    CONSTRAINT UQ_StaffService_StaffID_ServiceID UNIQUE (StaffID, ServiceID),
    CONSTRAINT CK_StaffService_ProficiencyLevel
        CHECK (ProficiencyLevel IN ('Beginner', 'Intermediate', 'Expert'))
);
GO


-- ==================================================================
-- Source: src/Tables/03_staff_time/dbo.StaffAvailability.sql
-- ==================================================================
-- StaffAvailability: a broad window a staff member has declared open for
-- booking, e.g. 2025-10-20 09:00-17:00 (1 Staff : many StaffAvailability).
-- Bookable TimeSlots are carved out of these windows.
-- Must be created AFTER dbo.Staff.
CREATE TABLE dbo.StaffAvailability (
    StaffAvailabilityID  INT IDENTITY(1,1) NOT NULL,
    StaffID              INT               NOT NULL,
    AvailabilityDate     DATE              NOT NULL,
    StartTime            TIME              NOT NULL,
    EndTime              TIME              NOT NULL,

    CONSTRAINT PK_StaffAvailability PRIMARY KEY (StaffAvailabilityID),
    CONSTRAINT FK_StaffAvailability_Staff
        FOREIGN KEY (StaffID) REFERENCES dbo.Staff (StaffID),
    -- The same window can't be declared twice for one staff member.
    CONSTRAINT UQ_StaffAvailability_StaffID_Date_StartTime
        UNIQUE (StaffID, AvailabilityDate, StartTime),
    CONSTRAINT CK_StaffAvailability_EndTime CHECK (StartTime < EndTime)
);
GO


-- ==================================================================
-- Source: src/Tables/03_staff_time/dbo.TimeSlot.sql
-- ==================================================================
-- TimeSlot: a discrete, service-length bookable chunk carved out of one
-- StaffAvailability window (1 StaffAvailability : many TimeSlots).
-- Referenced by AppointmentService.TimeSlotID.
-- A slot should fall inside its window (same date, between its start and
-- end times). A CHECK can't look at another table, so that rule is
-- verified in tests/03_staff_time_data_rows.sql instead.
-- Must be created AFTER dbo.StaffAvailability.
CREATE TABLE dbo.TimeSlot (
    TimeSlotID           INT IDENTITY(1,1) NOT NULL,
    StaffAvailabilityID  INT               NOT NULL,
    Date                 DATE              NOT NULL,
    StartTime            TIME              NOT NULL,
    EndTime              TIME              NOT NULL,

    CONSTRAINT PK_TimeSlot PRIMARY KEY (TimeSlotID),
    CONSTRAINT FK_TimeSlot_StaffAvailability
        FOREIGN KEY (StaffAvailabilityID) REFERENCES dbo.StaffAvailability (StaffAvailabilityID),
    CONSTRAINT CK_TimeSlot_EndTime CHECK (StartTime < EndTime)
);
GO


-- ==================================================================
-- Source: src/Tables/04_outcomes/dbo.Payment.sql
-- ==================================================================
-- Payment: one charge against an appointment, either a Deposit at booking
-- or a Full Payment at the visit (1 Appointment : many Payments).
-- PaymentMethodID is nullable because a stored card is optional
-- (M:0-1 PaymentMethod), e.g. a cash payment at the counter. When present,
-- the card must belong to the appointment's customer, which is verified in
-- tests/04_outcomes_data_rows.sql.
-- Must be created AFTER dbo.Appointment and dbo.PaymentMethod.
CREATE TABLE dbo.Payment (
    PaymentID       INT IDENTITY(1,1) NOT NULL,
    AppointmentID   INT NOT NULL,
    PaymentMethodID INT NULL,
    Amount          DECIMAL(10,2) NOT NULL,
    Status          VARCHAR(20) NOT NULL,
    ChargedAt       DATETIME NOT NULL,
    Type            VARCHAR(30) NOT NULL,

    CONSTRAINT PK_Payment PRIMARY KEY (PaymentID),
    CONSTRAINT FK_Payment_Appointment FOREIGN KEY (AppointmentID)
        REFERENCES dbo.Appointment (AppointmentID),
    CONSTRAINT FK_Payment_PaymentMethod FOREIGN KEY (PaymentMethodID)
        REFERENCES dbo.PaymentMethod (PaymentMethodID),
    CONSTRAINT CK_Payment_Amount CHECK (Amount >= 0),
    CONSTRAINT CK_Payment_Type CHECK (Type IN ('Deposit', 'Full Payment')),
    CONSTRAINT CK_Payment_Status CHECK (Status IN ('Pending', 'Completed', 'Failed', 'Refunded'))
);
GO


-- ==================================================================
-- Source: src/Tables/04_outcomes/dbo.Cancellation.sql
-- ==================================================================
-- Cancellation: the record of one cancelled appointment
-- (1 Appointment : 0-1 Cancellation, enforced by the UNIQUE constraint on
-- AppointmentID). FeeCharged follows the appointment location's
-- CancellationPolicy and is withheld from the deposit, and RefundAmount
-- is what's returned to the customer. CancelledBy is limited to
-- 'Customer' or 'Business', since the fee rule depends on which one it was.
-- Must be created AFTER dbo.Appointment.
CREATE TABLE dbo.Cancellation (
    CancellationID INT IDENTITY(1,1) NOT NULL,
    AppointmentID  INT NOT NULL,
    CancelledAt    DATETIME NOT NULL,
    CancelledBy    VARCHAR(50) NOT NULL,
    Reason         VARCHAR(255) NULL,
    FeeCharged     DECIMAL(10,2) NOT NULL,
    RefundAmount   DECIMAL(10,2) NOT NULL,

    CONSTRAINT PK_Cancellation PRIMARY KEY (CancellationID),
    CONSTRAINT FK_Cancellation_Appointment FOREIGN KEY (AppointmentID)
        REFERENCES dbo.Appointment (AppointmentID),
    CONSTRAINT UQ_Cancellation_AppointmentID UNIQUE (AppointmentID),
    CONSTRAINT CK_Cancellation_FeeCharged CHECK (FeeCharged >= 0),
    CONSTRAINT CK_Cancellation_RefundAmount CHECK (RefundAmount >= 0),
    CONSTRAINT CK_Cancellation_CancelledBy CHECK (CancelledBy IN ('Customer', 'Business'))
);
GO

-- ==================================================================
-- Source: src/Tables/04_outcomes/dbo.Notification.sql
-- ==================================================================
-- Notification: a message sent to a customer about one appointment
-- (1 Customer : many Notifications, 1 Appointment : many Notifications).
-- CustomerID must match the appointment's customer. A CHECK can't look at
-- another table, so that rule is verified in tests/04_outcomes_data_rows.sql.
-- Must be created AFTER dbo.Customer and dbo.Appointment.
CREATE TABLE dbo.Notification (
    NotificationID INT IDENTITY(1,1) NOT NULL,
    CustomerID     INT NOT NULL,
    AppointmentID  INT NOT NULL,
    Type           VARCHAR(30) NOT NULL,
    SentAt         DATETIME NOT NULL,
    DeliveryMethod VARCHAR(20) NOT NULL,

    CONSTRAINT PK_Notification PRIMARY KEY (NotificationID),
    CONSTRAINT FK_Notification_Customer FOREIGN KEY (CustomerID)
        REFERENCES dbo.Customer (CustomerID),
    CONSTRAINT FK_Notification_Appointment FOREIGN KEY (AppointmentID)
        REFERENCES dbo.Appointment (AppointmentID),
    CONSTRAINT CK_Notification_Type CHECK (Type IN ('Confirmation', 'Reminder', 'Cancellation')),
    CONSTRAINT CK_Notification_DeliveryMethod CHECK (DeliveryMethod IN ('Email', 'SMS', 'Phone'))
);
GO


-- ==================================================================
-- Source: src/Tables/05_appointment_service/dbo.AppointmentService.sql
-- ==================================================================
-- AppointmentService: one service booked within an appointment, i.e. the
-- line items of an Appointment (1 Appointment : many AppointmentServices).
-- Each row carries its own service, staff member, time slot, and status,
-- so one appointment can mix services with different staff, slots, and
-- outcomes. ParentAppointmentServiceID is a nullable self-reference: NULL
-- for a core service, or the core service row that an add-on belongs to.
-- Rules that compare rows or tables (the staff member owns the slot, the
-- add-on is in the same appointment as its parent, etc.) can't be CHECKs,
-- so they're verified in tests/05_appointment_service_data_rows.sql.
-- Must be created AFTER dbo.Appointment, dbo.Service, dbo.Staff, and
-- dbo.TimeSlot.
CREATE TABLE dbo.AppointmentService (
    AppointmentServiceID        INT IDENTITY(1,1) NOT NULL,
    AppointmentID               INT               NOT NULL,
    ServiceID                   INT               NOT NULL,
    ParentAppointmentServiceID  INT               NULL,
    TimeSlotID                  INT               NOT NULL,
    StaffID                     INT               NOT NULL,
    Status                      VARCHAR(20)       NOT NULL,

    CONSTRAINT PK_AppointmentService PRIMARY KEY (AppointmentServiceID),
    CONSTRAINT FK_AppointmentService_Appointment
        FOREIGN KEY (AppointmentID) REFERENCES dbo.Appointment (AppointmentID),
    CONSTRAINT FK_AppointmentService_Service
        FOREIGN KEY (ServiceID) REFERENCES dbo.Service (ServiceID),
    -- Self-reference: an add-on points to its core service row.
    CONSTRAINT FK_AppointmentService_ParentAppointmentService
        FOREIGN KEY (ParentAppointmentServiceID) REFERENCES dbo.AppointmentService (AppointmentServiceID),
    CONSTRAINT FK_AppointmentService_TimeSlot
        FOREIGN KEY (TimeSlotID) REFERENCES dbo.TimeSlot (TimeSlotID),
    CONSTRAINT FK_AppointmentService_Staff
        FOREIGN KEY (StaffID) REFERENCES dbo.Staff (StaffID),

    CONSTRAINT CK_AppointmentService_Status
        CHECK (Status IN ('Confirmed', 'Waitlisted', 'Cancelled', 'Completed')),
    -- A row can't be an add-on to itself. NULL (a core service) passes.
    CONSTRAINT CK_AppointmentService_ParentAppointmentServiceID
        CHECK (ParentAppointmentServiceID <> AppointmentServiceID)
);
GO

-- A time slot can be held by only one active booking. A filtered index is
-- used instead of a UNIQUE constraint so that cancelled and waitlisted rows
-- don't block the slot: a cancelled slot can be rebooked, and a waitlisted
-- customer is by definition waiting on a slot someone else holds.
CREATE UNIQUE INDEX UQ_AppointmentService_TimeSlotID
    ON dbo.AppointmentService (TimeSlotID)
    WHERE Status IN ('Confirmed', 'Completed');
GO
